import React, { useState } from 'react';
import axios from 'axios';

const CreateCliente = ({ setClientes, setSearchResult }) => {
  const [nome, setNome] = useState('');
  const [email, setEmail] = useState('');
  const [telefone, setTelefone] = useState('');
  const [search, setSearch] = useState('');

  // Função para criar um novo cliente
  const handleCreateCliente = async (e) => {
    e.preventDefault();
    try {
      const cliente = { nome, email, telefone };
      const response = await axios.post('http://localhost:8080/clientes', cliente);
      alert('Cliente criado com sucesso!');
      setNome('');
      setEmail('');
      setTelefone('');
    } catch (error) {
      console.error('Erro ao criar cliente:', error);
      alert('Erro ao criar cliente!');
    }
  };

  // Função para buscar cliente pelo nome
  const handleSearch = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.get(`http://localhost:8080/clientes?search=${search}`);
      setSearchResult(response.data);
    } catch (error) {
      console.error('Erro ao buscar cliente:', error);
      alert('Erro ao buscar cliente!');
    }
  };

  return (
    <div className="cliente-creation-or-search">
      <h2>Gestão de Clientes</h2>

      {/* Formulário de Criação de Cliente */}
      <div className="form-container">
        <h3>Criar Novo Cliente</h3>
        <form onSubmit={handleCreateCliente}>
          <input
            type="text"
            value={nome}
            onChange={(e) => setNome(e.target.value)}
            placeholder="Nome"
            required
          />
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="Email"
            required
          />
          <input
            type="tel"
            value={telefone}
            onChange={(e) => setTelefone(e.target.value)}
            placeholder="Telefone"
            required
          />
          <button type="submit">Criar Cliente</button>
        </form>
      </div>

      {/* Formulário de Busca de Cliente */}
      <div className="search-container">
        <h3>Buscar Cliente</h3>
        <form onSubmit={handleSearch}>
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Digite o nome do cliente"
          />
          <button type="submit">Buscar</button>
        </form>
      </div>
    </div>
  );
};

export default ClienteCreationOrSearch;
